// Bundles Capacitor's runtime + every native plugin's browser wrapper into
// app/vendor/capacitor-native.js. The app has no bundler, and the iOS shell
// only injects the low-level bridge — without this file Capacitor.Plugins is
// empty and every plugin call (camera, push, purchases…) silently no-ops.
// Run after `npm install`, before `npx cap sync ios` (codemagic.yaml does).
// index.html loads the result only inside the native app.
const fs = require('fs');
const path = require('path');
const nm = (p) => path.join(__dirname, '..', 'node_modules', p);

const parts = [
  ['@capacitor/core', 'dist/capacitor.js'],
  // RevenueCat's wrapper expects this global; it only uses it for web
  // mocks/enums, so a tiny stand-in is enough on iOS.
  [null, 'var purchasesTypescriptInternalEsm = { VERIFICATION_RESULT: { NOT_REQUESTED: "NOT_REQUESTED" }, REFUND_REQUEST_STATUS: { SUCCESS: 0, USER_CANCELLED: 1, ERROR: 2 } };'],
  ['@capacitor/camera', 'dist/plugin.js'],
  ['@capacitor/haptics', 'dist/plugin.js'],
  ['@capacitor/share', 'dist/plugin.js'],
  ['@capacitor/push-notifications', 'dist/plugin.js'],
  ['@capacitor/status-bar', 'dist/plugin.js'],
  ['@capacitor/splash-screen', 'dist/plugin.js'],
  ['@capacitor/keyboard', 'dist/plugin.js'],
  ['@capacitor/text-zoom', 'dist/plugin.js'],
  ['@revenuecat/purchases-capacitor', 'dist/plugin.js'],
  ['@capacitor/app', 'dist/plugin.js'],
  ['@capacitor/local-notifications', 'dist/plugin.js'],
  ['@capacitor/network', 'dist/plugin.js'],
  ['@capacitor/browser', 'dist/plugin.js'],
  // Face ID wrapper expects a global named `app` (its @capacitor/app import);
  // give it one in a private scope so nothing else can collide with it.
  [null, '(function (app) {'],
  ['@aparajita/capacitor-biometric-auth', 'dist/plugin.js'],
  [null, 'window.capacitorBiometricAuth = capacitorBiometricAuth; })(capacitorApp);'],
];

let out = '/* Generated by scripts/vendor-capacitor.js — do not edit. */\n';
for (const [pkg, file] of parts) {
  if (!pkg) { out += file + '\n'; continue; }
  const f = path.join(nm(pkg), file);
  if (!fs.existsSync(f)) { console.error('Missing ' + pkg + '/' + file + ' — run npm install'); process.exit(1); }
  out += '\n/* ' + pkg + ' */\n' + fs.readFileSync(f, 'utf8').replace(/\/\/# sourceMappingURL=.*$/gm, '') + '\n';
}
const dest = path.join(__dirname, '..', 'app', 'vendor', 'capacitor-native.js');
fs.mkdirSync(path.dirname(dest), { recursive: true });
fs.writeFileSync(dest, out);
console.log('Wrote ' + path.relative(process.cwd(), dest) + ' (' + Math.round(out.length / 1024) + ' KB, ' + (parts.length - 1) + ' parts)');
